-- (run AFTER schema.sql; replaces the placeholder empty-array seed row)
update blog_posts set
  content_en = '["Did you know where the tradition of using soy sauce, wasabi, and ginger comes from, and what they were actually used for in ancient Japan?", "<strong>生姜 - Ginger:</strong> In ancient times, before refrigerators existed, the Japanese used vinegar and spices to preserve fish. Ginger has natural antimicrobial properties and was originally added primarily for hygiene and safety.", "<figure class=\"post-figure\"><img src=\"images/blog-ginger.png\" alt=\"Ginger (生姜)\" loading=\"lazy\"><figcaption>Ginger (生姜)</figcaption></figure>", "<strong>How to eat it:</strong> It is never eaten together with a roll — it is a \"palate cleanser\" meant to be enjoyed between different bites to neutralize flavors.", "<strong>わさび - Wasabi:</strong> Real wasabi was a rare and expensive product in ancient Japan, placed alongside raw fish due to its antiseptic properties to neutralize bacteria.", "<figure class=\"post-figure\"><img src=\"images/blog-wasabi.png\" alt=\"Wasabi (わさび)\" loading=\"lazy\"><figcaption>Wasabi (わさび)</figcaption></figure>", "<strong>How to eat it:</strong> The chef already places the exact dose on your plate — dissolving wasabi into soy sauce disrupts the balance and ruins the dish''s original flavor.", "<strong>醤油 - Soy Sauce:</strong> The tradition of using soy sauce developed a little later, enhancing the unique umami flavor of raw fish (sashimi and sushi).", "<figure class=\"post-figure\"><img src=\"images/blog-soy-sauce.png\" alt=\"Soy Sauce (醤油)\" loading=\"lazy\"><figcaption>Soy Sauce (醤油)</figcaption></figure>", "<strong>How to eat it:</strong> Dip by the fish side, not the rice — rice quickly absorbs liquid, becomes overly soaked, and falls apart.", "Small tradition, big flavor! Drop by to put this knowledge into practice!"]'::jsonb,
  content_ka = '["იცით თუ არა, საიდან მოდის სოიოს, ვასაბისა და ჯანჯაფილის გამოყენების ტრადიცია და რეალურად რისთვის იყენებდნენ მათ ძველ იაპონიაში?", "<strong>生姜 - ჯანჯაფილი:</strong> ძველად, როდესაც მაცივრები არ არსებობდა, იაპონელები თევზის შესანახად ძმარსა და სანელებლებს იყენებდნენ. ჯანჯაფილს კი ბუნებრივი ანტიმიკრობული თვისებები აქვს და მას პირველ რიგში ჰიგიენისა და უსაფრთხოებისთვის ამატებდნენ.", "<figure class=\"post-figure\"><img src=\"images/blog-ginger.png\" alt=\"ჯანჯაფილი (生姜)\" loading=\"lazy\"><figcaption>ჯანჯაფილი (生姜)</figcaption></figure>", "<strong>როგორ მივირთვათ:</strong> ის არასდროს იჭმევა როლთან ერთად - ის არის „პირის გამწმენდი“, რომელსაც სხვადასხვა გემოს შორის მიირთმევენ, გემოების გასანეიტრებლად.", "<strong>わさび - ვასაბი:</strong> ნამდვილი ვასაბი ძველ იაპონიაში იშვიათი და ძვირად ღირებული პროდუქტი იყო, რომელსაც ანტისეპტიკური თვისებების გამო უმი თევზის გვერდით დებდნენ ბაქტერიების გასანეიტრებლად.", "<figure class=\"post-figure\"><img src=\"images/blog-wasabi.png\" alt=\"ვასაბი (わさび)\" loading=\"lazy\"><figcaption>ვასაბი (わさび)</figcaption></figure>", "<strong>როგორ მივირთვათ:</strong> შეფი უკვე დებს ზუსტ დოზას თეფშზე - ვასაბის სოიაში გახსნა კერძის ბალანსსა და მის თავდაპირველ გემოს არღვევს.", "<strong>醤油 - სოიოს სოუსი:</strong> სოიოს სოუსის გამოყენების ტრადიცია ოდნავ მოგვიანებით განვითარდა და ის უმი თევზის (საშიმის და სუშის) უნიკალურ უმამის გემოს აძლიერებს.", "<figure class=\"post-figure\"><img src=\"images/blog-soy-sauce.png\" alt=\"სოიოს სოუსი (醤油)\" loading=\"lazy\"><figcaption>სოიოს სოუსი (醤油)</figcaption></figure>", "<strong>როგორ მივირთვათ:</strong> ჩააწეთ თევზის მხრიდან და არა ბრინჯის - ბრინჯი სწრაფად შთანთქავს სითხეს, ზედმეტად იჟღინთება და იშლება.", "პატარა ტრადიცია, დიდი გემო! მობრძანდით, რომ ცოდნა პრაქტიკაში გამოსცადოთ!"]'::jsonb,
  content_ru = '["Знаете ли вы, откуда происходит традиция использования соевого соуса, васаби и имбиря, и для чего на самом деле они использовались в древней Японии?", "<strong>生姜 - Имбирь:</strong> В древние времена, когда не было холодильников, японцы использовали уксус и специи для сохранения рыбы. Имбирь обладает природными антимикробными свойствами и изначально добавлялся в первую очередь для гигиены и безопасности.", "<figure class=\"post-figure\"><img src=\"images/blog-ginger.png\" alt=\"Имбирь (生姜)\" loading=\"lazy\"><figcaption>Имбирь (生姜)</figcaption></figure>", "<strong>Как есть:</strong> Его никогда не едят вместе с роллами — это «очиститель вкуса», который едят между разными блюдами для нейтрализации вкусов.", "<strong>わさび - Васаби:</strong> Настоящий васаби в древней Японии был редким и дорогим продуктом, который клали рядом с сырой рыбой из-за его антисептических свойств для нейтрализации бактерий.", "<figure class=\"post-figure\"><img src=\"images/blog-wasabi.png\" alt=\"Васаби (わさび)\" loading=\"lazy\"><figcaption>Васаби (わさび)</figcaption></figure>", "<strong>Как есть:</strong> Шеф-повар уже кладет точную дозу на тарелку — растворение васаби в соевом соусе нарушает баланс и первоначальный вкус блюда.", "<strong>醤油 - Соевый соус:</strong> Традиция использования соевого соуса развилась чуть позже, он усиливает уникальный умами-вкус сырой рыбы (сашими и суши).", "<figure class=\"post-figure\"><img src=\"images/blog-soy-sauce.png\" alt=\"Соевый соус (醤油)\" loading=\"lazy\"><figcaption>Соевый соус (醤油)</figcaption></figure>", "<strong>Как есть:</strong> Макайте стороной рыбы, а не риса — рис быстро впитывает жидкость, перенасыщается и разваливается.", "Маленькая традиция, большой вкус! Загляните к нам, чтобы применить эти знания на практике!"]'::jsonb
where slug = 'how-to-eat-sushi-properly';
